local _K = 202

local function SwICnKo(a, b)
    local r, p = 0, 1
    while a > 0 or b > 0 do
        local a2, b2 = a % 2, b % 2
        if a2 ~= b2 then r = r + p end
        a, b, p = (a - a2) / 2, (b - b2) / 2, p * 2
    end
    return r
end

